@startuml

class Well {
  + code : string
}

class Company {
  + taxCode : string
  + numberOfEmployees : int
}

class PollutionRate {
  + rate : double
}

class OnshoreWell {
  + surfaceExtension : float
}

class OffshoreWell {
  + yearOfInstallation : int
  + geographicalArea : GeographicalArea
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

Company "0..*" -- "*" Well : extractsFrom
OnshoreWell "1" -- "1" Well : is
OffshoreWell "1" -- "1" Well : is
PollutionRate "1" -- "1" Well : calculatesFor

@enduml

